    <meta charset="UTF-8" />
    <meta name="viewport" content="width=device-width, initial-scale=1.0" />
    <title>Notification Preferences</title>
    <style>
      :root {
        color-scheme: dark;
        --bg: #111827;
        --panel: #1f2937;
        --panel-border: #374151;
        --text: #f9fafb;
        --muted: #cbd5e1;
        --accent: #60a5fa;
        --accent-strong: #3b82f6;
        --option-bg: #0f172a;
        --option-border: #475569;
        --button-text: #eff6ff;
      }

      * {
        box-sizing: border-box;
      }

      body {
        margin: 0;
        min-height: 100vh;
        font-family: Arial, Helvetica, sans-serif;
        background:
          radial-gradient(circle at top, #1e3a8a 0, transparent 35%),
          linear-gradient(180deg, #0b1120 0%, var(--bg) 100%);
        color: var(--text);
        display: grid;
        place-items: center;
        padding: 24px;
      }

      .skip-link {
        position: absolute;
        left: 16px;
        top: 16px;
        transform: translateY(-200%);
        background: #ffffff;
        color: #111827;
        padding: 0.75rem 1rem;
        border-radius: 0.75rem;
        text-decoration: none;
        font-weight: 700;
      }

      .skip-link:focus {
        transform: translateY(0);
      }

      main {
        width: min(100%, 520px);
      }

      .card {
        background: linear-gradient(180deg, rgba(31, 41, 55, 0.96), rgba(15, 23, 42, 0.96));
        border: 1px solid rgba(148, 163, 184, 0.18);
        border-radius: 20px;
        padding: 32px;
        box-shadow: 0 24px 60px rgba(0, 0, 0, 0.45);
        backdrop-filter: blur(8px);
      }

      h1 {
        margin: 0 0 12px;
        font-size: clamp(1.8rem, 4vw, 2.4rem);
      }

      p {
        margin: 0 0 24px;
        color: var(--muted);
        line-height: 1.5;
      }

      .form-field {
        margin-bottom: 24px;
      }

      fieldset {
        margin: 0;
        padding: 0;
        border: 0;
      }

      legend {
        font-size: 1.05rem;
        font-weight: 700;
        margin-bottom: 16px;
      }

      .option-list {
        display: grid;
        gap: 12px;
      }

      .option {
        display: flex;
        align-items: center;
        gap: 14px;
        padding: 16px 18px;
        border: 1px solid var(--option-border);
        border-radius: 14px;
        background: rgba(15, 23, 42, 0.95);
        cursor: pointer;
        transition: border-color 0.2s ease, transform 0.2s ease, background 0.2s ease;
      }

      .option:hover {
        border-color: #64748b;
        transform: translateY(-1px);
      }

      .option:focus-within {
        outline: 2px solid transparent;
        border-color: var(--accent);
        box-shadow: 0 0 0 3px rgba(96, 165, 250, 0.3);
      }

      input[type="radio"] {
        width: 1.15rem;
        height: 1.15rem;
        margin: 0;
        accent-color: var(--accent-strong);
      }

      .option-text {
        font-size: 1rem;
        font-weight: 600;
      }

      button {
        width: 100%;
        border: 0;
        border-radius: 14px;
        padding: 14px 18px;
        font-size: 1rem;
        font-weight: 700;
        color: var(--button-text);
        background: linear-gradient(135deg, var(--accent-strong), #2563eb);
        cursor: pointer;
        transition: transform 0.2s ease, filter 0.2s ease;
      }

      button:hover {
        filter: brightness(1.08);
        transform: translateY(-1px);
      }

      button:focus-visible,
      input[type="radio"]:focus-visible {
        outline: 2px solid #bfdbfe;
        outline-offset: 3px;
      }

      .status {
        min-height: 1.5rem;
        margin-top: 16px;
        color: #bfdbfe;
        font-weight: 600;
      }

      @media (max-width: 480px) {
        .card {
          padding: 24px;
        }
      }

      @media (forced-colors: active) {
        body {
          background: Canvas;
          color: CanvasText;
        }

        .card,
        .option,
        button {
          background: Canvas;
          color: CanvasText;
          border: 1px solid ButtonText;
          box-shadow: none;
        }

        .skip-link {
          background: Canvas;
          color: LinkText;
          border: 1px solid LinkText;
        }
      }
    </style>
  </head>
  <body>
    <a class="skip-link" href="#main-content">Skip to main content</a>
    <main id="main-content">
      <section class="card" aria-labelledby="page-title">
        <h1 id="page-title">Notification Preferences</h1>
        <p>Select the best way for us to keep you informed.</p>

        <form id="preferences-form">
          <div class="form-field">
            <fieldset>
              <legend>How do you prefer to receive notifications?</legend>
              <div class="option-list">
                <label class="option" for="notification-email">
                  <input
                    id="notification-email"
                    type="radio"
                    name="notification"
                    value="Email"
                    required
                  />
                  <span class="option-text">Email</span>
                </label>

                <label class="option" for="notification-sms">
                  <input
                    id="notification-sms"
                    type="radio"
                    name="notification"
                    value="SMS"
                  />
                  <span class="option-text">SMS</span>
                </label>

                <label class="option" for="notification-push">
                  <input
                    id="notification-push"
                    type="radio"
                    name="notification"
                    value="Push Notifications"
                  />
                  <span class="option-text">Push Notifications</span>
                </label>
              </div>
            </fieldset>
          </div>

          <button type="submit">Submit</button>
          <p id="form-status" class="status" aria-live="polite"></p>
        </form>
      </section>
    </main>

    <script>
      const form = document.getElementById("preferences-form");
      const status = document.getElementById("form-status");

      form.addEventListener("submit", (event) => {
        event.preventDefault();

        const selection = form.querySelector('input[name="notification"]:checked');
        status.textContent = selection
          ? `Preference saved: ${selection.value}.`
          : "Please choose a notification method before submitting.";
      });
    </script>
  </body>
</html>
